<?php $title='Portfolio';require '_head.php';$msg='';
try{
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM portfolio WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: portfolio.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$image=upload_image($_FILES['image']??null,'portfolio');$pdo->prepare('INSERT INTO portfolio(title,description,image,sort_order,active) VALUES(?,?,?,0,1)')->execute([$_POST['title'],$_POST['description'],$image]);header('Location: portfolio.php?saved=1');exit;}
}catch(Throwable $e){$msg=$e->getMessage();}
$rows=$pdo->query('SELECT * FROM portfolio ORDER BY id DESC')->fetchAll();?><h1>Portfolio</h1><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form method="post" enctype="multipart/form-data"><input name="title" placeholder="Judul" required><textarea name="description" placeholder="Deskripsi"></textarea><label class="upload-label">Foto portfolio<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG, WebP • maksimal 5 MB</small></label><button>Simpan</button></form></div><div class="panel"><?php foreach($rows as $r):?><p><?php if($r['image']):?><img class="thumb" src="<?=e($r['image'])?>" alt=""><?php endif;?> <?=e($r['title'])?> — <a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></p><?php endforeach;?></div><?php require '_foot.php';?>